const numbers = [args.a, args.b, args.a + args.b, args.a * args.b];
const encoded = encode(numbers);
const decoded = decode(encoded);
const encodedNegative = encode(-args.a);
const encodedZero = encode(0n);

console.log(pyBytesRepr(encoded));
console.log(pyListRepr(decoded));
console.log(pyBytesRepr(encodedNegative));
console.log(pyBytesRepr(encodedZero));

