export function pyBytesRepr(s) {
  let out = "b'";
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = ch.charCodeAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === "'") {
      out += "\\'";
    } else if (code >= 0x20 && code < 0x7f) {
      out += ch;
    } else {
      out += '\\x' + code.toString(16).padStart(2, '0');
    }
  }
  out += "'";
  return out;
}

function pyRepr(v) {
  if (typeof v === 'bigint' || typeof v === 'number') {
    return String(v);
  }
  if (typeof v === 'string') {
    return pyBytesRepr(v);
  }
  if (Array.isArray(v)) {
    return pyListRepr(v);
  }
  return String(v);
}

export function pyListRepr(arr) {
  return '[' + arr.map(pyRepr).join(', ') + ']';
}

