// Bencode decoder: parses a plain ASCII string into JS values.
// Integers decode to BigInt, lists to Array, byte strings to String.

export function decode(str) {
  let pos = 0;

  function isDigit(ch) {
    return ch >= "0" && ch <= "9";
  }

  function parseValue() {
    if (pos >= str.length) {
      throw new Error("bencode: unexpected end of data");
    }
    const ch = str[pos];
    if (ch === "i") return parseInt_();
    if (ch === "l") return parseList();
    if (isDigit(ch)) return parseByteString();
    throw new Error("bencode: invalid character '" + ch + "' at position " + pos);
  }

  function parseInt_() {
    pos++; // skip 'i'
    const start = pos;
    if (str[pos] === "-") pos++;
    const digitsStart = pos;
    while (pos < str.length && isDigit(str[pos])) pos++;
    if (pos === digitsStart) {
      throw new Error("bencode: integer with no digits at position " + start);
    }
    if (pos >= str.length || str[pos] !== "e") {
      throw new Error("bencode: integer missing 'e' terminator at position " + start);
    }
    const text = str.slice(start, pos);
    pos++; // skip 'e'
    return BigInt(text);
  }

  function parseList() {
    pos++; // skip 'l'
    const items = [];
    while (true) {
      if (pos >= str.length) {
        throw new Error("bencode: list missing 'e' terminator");
      }
      if (str[pos] === "e") {
        pos++;
        return items;
      }
      items.push(parseValue());
    }
  }

  function parseByteString() {
    const start = pos;
    while (pos < str.length && isDigit(str[pos])) pos++;
    if (pos >= str.length || str[pos] !== ":") {
      throw new Error("bencode: byte string length missing ':' at position " + start);
    }
    const len = Number(str.slice(start, pos));
    pos++; // skip ':'
    if (pos + len > str.length) {
      throw new Error("bencode: byte string truncated at position " + pos);
    }
    const value = str.slice(pos, pos + len);
    pos += len;
    return value;
  }

  const result = parseValue();
  if (pos !== str.length) {
    throw new Error("bencode: trailing data at position " + pos);
  }
  return result;
}

