// Minimal argparse mimic for exactly two required int options: --a and --b.

function progName() {
  const script = process.argv[1] || '';
  const parts = script.split('/');
  return parts[parts.length - 1] || script;
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function parseIntValue(prog, optName, raw) {
  const trimmed = raw.trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    fail(prog, `argument ${optName}: invalid int value: '${raw}'`);
  }
  return BigInt(trimmed);
}

export function parseArgs(argv) {
  const prog = progName();
  const values = { a: undefined, b: undefined };
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    let optName = null;
    let inlineValue = null;

    if (token === '--a' || token === '--b') {
      optName = token;
    } else if (token.startsWith('--a=')) {
      optName = '--a';
      inlineValue = token.slice('--a='.length);
    } else if (token.startsWith('--b=')) {
      optName = '--b';
      inlineValue = token.slice('--b='.length);
    }

    if (optName === null) {
      extras.push(token);
      continue;
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
    } else {
      if (i + 1 >= argv.length) {
        fail(prog, `argument ${optName}: expected one argument`);
      }
      raw = argv[++i];
    }

    values[optName === '--a' ? 'a' : 'b'] = parseIntValue(prog, optName, raw);
  }

  const missing = [];
  if (values.a === undefined) missing.push('--a');
  if (values.b === undefined) missing.push('--b');
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values.a, b: values.b };
}

